// Package chart reads the Helm chart this repository ships.
//
// Why this package exists: the chart is identity's deploy artifact, and
// like every other artifact in this repository it is held to its contract
// by a test that reads it off disk — the same discipline openapi_drift_test
// applies to openapi/v1.yaml. The chart is generated by `caf gen chart`,
// whose source lives in another repository, so nothing else checks that
// the generated facts (the chart's name, its version, the container port,
// the readiness path) still agree with the service the chart deploys and
// with the Dockerfile that builds its image.
//
// Why this is not a YAML parser: go.mod has no YAML dependency and this
// package adds none. The house rule is "no dependency without a cause
// stated in review", and the openapi reader's rationale applies verbatim —
// a YAML library already in the module graph as a transitive dependency
// would become this service's direct requirement, with its versions and
// its CVEs, for the sake of reading a handful of files this repository
// also generates by hand. The subset this reader understands is stated in
// parseFile's doc comment, and every way it could come back with less
// than it should is an error, not an empty result.
package chart

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// Root is the chart directory, relative to this package's own directory
// (internal/chart → repository root → chart). The test reads the chart
// through it, so the proof runs from any working directory and needs no
// database.
const Root = "../../chart"

// The files `caf gen chart` writes. Seven, of which this repository keeps
// six: templates/application.yaml is emitted by the generator and deleted
// here on purpose — the substrate owns the Argo Application (DEPLOYMENT.md,
// "Who owns the Application, and where a service lands"), and two
// Applications of one name and namespace with different sources fight each
// other. The generator's emission of it is a caf-side bug, tracked as the
// caf packet that removes it; this repository deletes the file and does
// not edit caf.
var GeneratedFiles = []string{
	"Chart.yaml",
	"values.yaml",
	"templates/deployment.yaml",
	"templates/service.yaml",
	"templates/ingress.yaml",
	"templates/application.yaml", // deleted here; see README.md
	"README.md",
}

// KeptFiles are the files the chart holds after the deletion. The test
// asserts each exists, so a chart missing one is a red test rather than a
// silent gap.
var KeptFiles = []string{
	"Chart.yaml",
	"values.yaml",
	"templates/deployment.yaml",
	"templates/service.yaml",
	"templates/ingress.yaml",
	"README.md",
}

// yamlMap is one parsed YAML mapping. Values are string, yamlMap, or
// []any — the three shapes the chart's files use.
type yamlMap = map[string]any

// parseFile reads one YAML file into a generic tree.
//
// The subset, stated because anything outside it is an error rather than
// a guess:
//
//   - `key: value` pairs, nested by indentation (the step is derived from
//     the document, not assumed to be two);
//   - `key:` with nothing after it opens a nested block — a mapping or,
//     where the next line starts with `-`, a list;
//   - `- ` starts a list item; an item is a scalar, or a mapping whose
//     first pair sits on the dash line and whose remaining pairs are
//     indented past it;
//   - a value may be single- or double-quoted; the quotes are stripped
//     and the contents kept verbatim, so a Helm template string such as
//     `"{{ .Values.image.tag }}"` parses as one scalar;
//   - a line whose first non-space characters are `{{` is a Helm action
//     (if/range/end and friends) and is skipped, not parsed — the chart's
//     templates are Helm first and YAML second;
//   - `#` comments and blank lines are skipped.
//
// Every way this could come back with less than the file holds — a
// missing file, a key the caller asked for and did not find, a list
// index out of range — is an error. A reader that finds nothing agrees
// with another reader that finds nothing, and that is how a check over
// nothing goes green.
func parseFile(path string) (yamlMap, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}

	var lines []yamlLine
	for _, raw := range strings.Split(string(data), "\n") {
		line := stripComment(raw)
		trimmed := strings.TrimLeft(line, " \t")
		if trimmed == "" {
			continue
		}
		if strings.HasPrefix(trimmed, "{{") {
			continue
		}
		lines = append(lines, yamlLine{
			indent:  len(line) - len(trimmed),
			content: trimmed,
		})
	}

	if len(lines) == 0 {
		return nil, fmt.Errorf("%s: no YAML content found", path)
	}

	doc, _, err := parseBlock(lines, 0, lines[0].indent)
	if err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}
	m, ok := doc.(yamlMap)
	if !ok {
		return nil, fmt.Errorf("%s: top level is a list, want a mapping", path)
	}
	return m, nil
}

// yamlLine is one significant line of a YAML file: its indentation and
// its content with the indentation and any comment removed.
type yamlLine struct {
	indent  int
	content string
}

// stripComment removes a trailing `#` comment, ignoring `#` inside quotes.
func stripComment(s string) string {
	inSingle, inDouble := false, false
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle {
				inDouble = !inDouble
			}
		case '#':
			if !inSingle && !inDouble && (i == 0 || s[i-1] == ' ' || s[i-1] == '\t') {
				return s[:i]
			}
		}
	}
	return s
}

// parseBlock parses the lines at i, which must all be at indent, and
// returns the value plus the index of the first line it did not consume.
func parseBlock(lines []yamlLine, i, indent int) (any, int, error) {
	if strings.HasPrefix(lines[i].content, "-") {
		return parseList(lines, i, indent)
	}
	return parseMap(lines, i, indent)
}

// parseMap parses a mapping whose entries are exactly at indent.
func parseMap(lines []yamlLine, i, indent int) (yamlMap, int, error) {
	m := yamlMap{}
	for i < len(lines) {
		ln := lines[i]
		if ln.indent < indent {
			break
		}
		if ln.indent > indent {
			return nil, i, fmt.Errorf("line %d: unexpected indent", i+1)
		}
		key, value, hasValue := splitKV(ln.content)
		if key == "" {
			return nil, i, fmt.Errorf("line %d: cannot parse %q", i+1, ln.content)
		}
		if !hasValue {
			if i+1 >= len(lines) || lines[i+1].indent <= ln.indent {
				return nil, i, fmt.Errorf("line %d: key %q has no value and no nested block", i+1, key)
			}
			child, next, err := parseBlock(lines, i+1, lines[i+1].indent)
			if err != nil {
				return nil, next, err
			}
			m[key] = child
			i = next
			continue
		}
		m[key] = parseScalar(value)
		i++
	}
	return m, i, nil
}

// parseList parses a list whose dash items are exactly at indent.
func parseList(lines []yamlLine, i, indent int) ([]any, int, error) {
	var list []any
	for i < len(lines) {
		ln := lines[i]
		if ln.indent < indent || !strings.HasPrefix(ln.content, "-") {
			break
		}
		if ln.indent > indent {
			return nil, i, fmt.Errorf("line %d: unexpected indent in list", i+1)
		}
		rest := strings.TrimLeft(strings.TrimPrefix(ln.content, "-"), " ")
		if rest == "" {
			// The item is a nested block on the following lines.
			if i+1 >= len(lines) || lines[i+1].indent <= ln.indent {
				return nil, i, fmt.Errorf("line %d: list item with no content", i+1)
			}
			child, next, err := parseBlock(lines, i+1, lines[i+1].indent)
			if err != nil {
				return nil, next, err
			}
			list = append(list, child)
			i = next
			continue
		}
		key, value, hasValue := splitKV(rest)
		if !hasValue {
			if key == "" {
				return nil, i, fmt.Errorf("line %d: cannot parse list item %q", i+1, rest)
			}
			// `- key:` — a mapping item whose first key opens a
			// nested block (the Deployment's envFrom is this shape).
			if i+1 >= len(lines) || lines[i+1].indent <= ln.indent {
				return nil, i, fmt.Errorf("line %d: list item %q has no value and no nested block", i+1, key)
			}
			child, next, err := parseBlock(lines, i+1, lines[i+1].indent)
			if err != nil {
				return nil, next, err
			}
			item := yamlMap{key: child}
			i = next
			for i < len(lines) && lines[i].indent > ln.indent {
				sub, next, err := parseMap(lines, i, lines[i].indent)
				if err != nil {
					return nil, next, err
				}
				for k, v := range sub {
					item[k] = v
				}
				i = next
			}
			list = append(list, item)
			continue
		}
		item := yamlMap{key: parseScalar(value)}
		i++
		// Remaining pairs of a mapping item are indented past the dash.
		for i < len(lines) && lines[i].indent > ln.indent {
			sub, next, err := parseMap(lines, i, lines[i].indent)
			if err != nil {
				return nil, next, err
			}
			for k, v := range sub {
				item[k] = v
			}
			i = next
		}
		list = append(list, item)
	}
	return list, i, nil
}

// splitKV splits `key: value` on the first colon that is followed by a
// space or ends the line. A colon inside a quoted value does not split.
func splitKV(s string) (key, value string, hasValue bool) {
	inSingle, inDouble := false, false
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle {
				inDouble = !inDouble
			}
		case ':':
			if inSingle || inDouble {
				continue
			}
			if i == len(s)-1 {
				return strings.TrimSpace(s[:i]), "", false
			}
			if s[i+1] == ' ' {
				return strings.TrimSpace(s[:i]), strings.TrimSpace(s[i+1:]), true
			}
		}
	}
	return "", "", false
}

// parseScalar strips one layer of matching quotes and keeps everything
// else verbatim — including Helm template actions, which are values here
// and not structure.
func parseScalar(s string) any {
	if len(s) >= 2 {
		if (s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '\'' && s[len(s)-1] == '\'') {
			return s[1 : len(s)-1]
		}
	}
	return s
}

// child returns key's value in m. A key this reader is asked for and does
// not find is an error, not a zero value: the alternative is a check that
// passes against a document missing the fact it exists to hold.
func child(m yamlMap, key string) (any, error) {
	v, ok := m[key]
	if !ok {
		return nil, fmt.Errorf("key %q not found", key)
	}
	return v, nil
}

// childMap returns key's value in m as a mapping.
func childMap(m yamlMap, key string) (yamlMap, error) {
	v, err := child(m, key)
	if err != nil {
		return nil, err
	}
	cm, ok := v.(yamlMap)
	if !ok {
		return nil, fmt.Errorf("key %q is not a mapping", key)
	}
	return cm, nil
}

// childList returns key's value in m as a list.
func childList(m yamlMap, key string) ([]any, error) {
	v, err := child(m, key)
	if err != nil {
		return nil, err
	}
	l, ok := v.([]any)
	if !ok {
		return nil, fmt.Errorf("key %q is not a list", key)
	}
	return l, nil
}

// listItem returns index i of l, refusing to range.
func listItem(l []any, i int, path string) (any, error) {
	if i >= len(l) {
		return nil, fmt.Errorf("%s: index %d out of range (list holds %d)", path, i, len(l))
	}
	return l[i], nil
}

// scalarString returns v as the string it must be.
func scalarString(v any, path string) (string, error) {
	s, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("%s is not a scalar", path)
	}
	return s, nil
}

// resolveRoot returns the absolute path of the chart directory.
func resolveRoot() (string, error) {
	return filepath.Abs(Root)
}
